style.css:
@-moz-document domain("youtube.com") {
/* ------------------------------
     Global glossy background
  ------------------------------ */
  body, ytd-app {
    background: #0e1116 !important;
    color: #e8ecf0 !important;
  }

  /* Subtle glass effect */
  #container.ytd-masthead {
    background: rgba(255,255,255,0.04) !important;
    backdrop-filter: blur(10px) saturate(160%);
    border-bottom: 1px solid rgba(255,255,255,0.05);
  }

  /* ------------------------------
     Search bar glow
  ------------------------------ */
  #search {
    border-radius: 40px !important;
    background: rgba(255,255,255,0.06) !important;
    box-shadow: 0 0 12px rgba(110,231,255,0.2);
    transition: .25s ease;
  }
  #search:focus-within {
    box-shadow: 0 0 22px rgba(110,231,255,0.55);
  }

  /* ------------------------------
     Thumbnail glow + lift
  ------------------------------ */
  ytd-thumbnail #thumbnail {
    border-radius: 12px !important;
    transition: 0.22s ease;
    box-shadow: 0 6px 16px rgba(0,0,0,0.55);
  }
  ytd-thumbnail:hover #thumbnail {
    transform: scale(1.03);
    box-shadow: 0 0 25px rgba(110,231,255,0.45);
  }

  /* ------------------------------
     Video cards glossy effect
  ------------------------------ */
  ytd-rich-grid-media,
  ytd-video-renderer {
    background: rgba(255,255,255,0.03) !important;
    border-radius: 14px !important;
    padding: 10px !important;
    transition: 0.25s ease;
  }

  ytd-rich-grid-media:hover,
  ytd-video-renderer:hover {
    background: rgba(255,255,255,0.06) !important;
    box-shadow: 0 0 18px rgba(110,231,255,0.25);
    transform: translateY(-4px);
  }

  /* ------------------------------
     Sidebar glow on hover
  ------------------------------ */
  ytd-guide-entry-renderer:hover {
    background: rgba(110,231,255,0.1) !important;
    border-radius: 10px !important;
    box-shadow: 0 0 18px rgba(110,231,255,0.4);
  }

  /* ------------------------------
     Video player progress bar glow
  ------------------------------ */
  .ytp-progress-bar-container,
  .ytp-play-progress {
    background: linear-gradient(90deg, #6ee7ff, #7df5d8) !important;
    height: 5px !important;
    border-radius: 10px !important;
  }

  /* ------------------------------
     Buttons glossy + glow
  ------------------------------ */
  ytd-button-renderer yt-button-shape button {
    background: rgba(255,255,255,0.07) !important;
    border-radius: 10px !important;
    transition: .2s ease;
  }

  ytd-button-renderer yt-button-shape button:hover {
    background: rgba(110,231,255,0.18) !important;
    box-shadow: 0 0 14px rgba(110,231,255,0.45);
  }

  /* ------------------------------
     Remove clutter for cleaner UI
  ------------------------------ */
  #comments {
    display: none !important; /* remove comments */
  }
  ytd-rich-shelf-renderer[is-shorts] {
    display: none !important; /* remove shorts row */
  }
}
